CREATE OR REPLACE FUNCTION public.get_book_vendor_counts(_book_id uuid) RETURNS TABLE(nigerian_count bigint,online_count bigint,total_count bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT count(*) FILTER (WHERE v.type='Nigerian Vendor'), count(*) FILTER (WHERE v.type='Online Store'), count(*) FROM public.book_vendors bv JOIN public.vendors v ON v.id=bv.vendor_id WHERE bv.book_id=_book_id $$; GRANT EXECUTE ON FUNCTION public.get_book_vendor_counts(uuid) TO anon,authenticated,service_role;